<?php
declare(strict_types=1);
namespace App\Application\Academic\Commands;
use Illuminate\Database\Connection;
use App\Infrastructure\Authentication\AuthenticatedActor;
use App\Application\Academic\AcademicCommandFailure;
use App\Infrastructure\Persistence\Academic\{AcademicLockSet,AcademicWriteTransaction,AcademicMutationResult,LifecycleEvent,AcademicTransactionFailure,LocalMaterialStorage,DeliveryFileValidator};
final class ActivityDelivery {
 public function __construct(private Connection $db,private LocalMaterialStorage $storage){}
 private function roles(AuthenticatedActor $actor):array {FoundationCommandChecks::credentials($this->db,$actor);if($this->db->table('retained_identities')->where('id',$actor->identityId)->value('credential_status')!=='active')throw new AcademicCommandFailure('forbidden');return $this->db->table('local_role_grants')->where('identity_id',$actor->identityId)->pluck('role')->all();}
 private function assignment(string $id):array {$row=$this->db->table('teaching_assignments')->where('id',AcademicLockSet::id($id))->first();if(!$row)throw new AcademicCommandFailure('not_found');return (array)$row;}
 private function content(string $id):array {$row=$this->db->table('activity_references as r')->join('activity_contents as c','c.activity_id','=','r.id')->where('r.id',AcademicLockSet::id($id))->first(['r.teaching_assignment_id','c.*']);if(!$row)throw new AcademicCommandFailure('not_found');return (array)$row;}
 private function enrollments(AuthenticatedActor $actor,array $assignment):array{return $this->db->table('student_enrollments')->where('student_id',$actor->identityId)->where('academic_period_id',$assignment['academic_period_id'])->where('grade_id',$assignment['grade_id'])->where('section_id',$assignment['section_id'])->get()->map(fn($r)=>(array)$r)->all();}
 private function canRead(AuthenticatedActor $actor,array $activity):bool {
  $roles=$this->roles($actor);$a=$this->assignment((string)$activity['teaching_assignment_id']);if(in_array('teacher',$roles,true)&&(string)$a['teacher_id']===$actor->identityId)return true;
  if(!in_array('student',$roles,true))return false;
  if($this->db->table('activity_deliveries')->where('activity_id',$activity['activity_id'])->where('student_id',$actor->identityId)->exists())return true;
  $activePeriod=$this->db->table('academic_periods')->where('id',$a['academic_period_id'])->value('state')==='active';
  foreach($this->enrollments($actor,$a) as $e){if($activePeriod&&$e['state']==='active')return true;if($e['operational_start_key']!==null&&(int)$activity['publication_key']>=(int)$e['operational_start_key']&&($e['operational_end_key']===null||(int)$activity['publication_key']<(int)$e['operational_end_key']))return true;}return false;
 }
 public function courses(AuthenticatedActor $actor,?string $after):array {
  $roles=$this->roles($actor);if(!array_intersect($roles,['teacher','student']))throw new AcademicCommandFailure('forbidden');
  $query=$this->db->table('teaching_assignments as a')->join('instructional_entries as e','e.id','=','a.instructional_entry_id')->join('grades as g','g.id','=','a.grade_id')->join('sections as s','s.id','=','a.section_id')->join('academic_periods as p','p.id','=','a.academic_period_id')
   ->where(function($q)use($actor,$roles){if(in_array('teacher',$roles,true))$q->where('a.teacher_id',$actor->identityId);if(in_array('student',$roles,true))$q->orWhereExists(function($en)use($actor){$en->selectRaw('1')->from('student_enrollments as en')->where('en.student_id',$actor->identityId)->whereColumn('en.academic_period_id','a.academic_period_id')->whereColumn('en.grade_id','a.grade_id')->whereColumn('en.section_id','a.section_id')->where(function($elig){$elig->where(function($current){$current->where('en.state','active')->where('p.state','active');})->orWhereExists(function($hist){$hist->selectRaw('1')->from('activity_references as r')->join('activity_contents as c','c.activity_id','=','r.id')->whereColumn('r.teaching_assignment_id','a.id')->whereColumn('c.publication_key','>=','en.operational_start_key')->where(function($end){$end->whereNull('en.operational_end_key')->orWhereColumn('c.publication_key','<','en.operational_end_key');});});});});});
  if($after!==null)$query->where('a.id','>',AcademicLockSet::id($after));$rows=$query->orderBy('a.id')->limit(51)->get(['a.id','a.teacher_id','a.state','p.state as period_state','e.name','g.name as grade','s.name as section','p.name as period']);$more=$rows->count()>50;
  $items=$rows->take(50)->map(fn($r)=>['id'=>(string)$r->id,'label'=>$r->name.' · '.$r->grade.' '.$r->section.' · '.$r->period,'can_publish'=>(string)$r->teacher_id===$actor->identityId&&in_array('teacher',$roles,true)&&$r->state==='active'&&$r->period_state==='active'])->values()->all();return ['items'=>$items,'next_after'=>$more?end($items)['id']:null];
 }
 public function activity(AuthenticatedActor $actor,string $id):array {$row=$this->content($id);if(!$this->canRead($actor,$row))throw new AcademicCommandFailure('not_found');return $row;}
 private function currentEnrollment(AuthenticatedActor $actor,array $a):?array {$rows=array_values(array_filter($this->enrollments($actor,$a),fn($e)=>$e['state']==='active'&&$e['operational_start_key']!==null));return count($rows)===1?$rows[0]:null;}
 public function view(AuthenticatedActor $actor,array $row):array {
  $a=$this->assignment((string)$row['teaching_assignment_id']);$roles=$this->roles($actor);$active=$this->db->table('academic_periods')->where('id',$a['academic_period_id'])->value('state')==='active';$e=$this->currentEnrollment($actor,$a);$delivery=$this->db->table('activity_deliveries as d')->join('submission_references as r','r.id','=','d.submission_id')->where('d.activity_id',$row['activity_id'])->where('d.student_id',$actor->identityId)->first();
  return ['id'=>(string)$row['activity_id'],'assignment_id'=>(string)$row['teaching_assignment_id'],'title'=>$row['title'],'instructions'=>$row['instructions'],'due_on'=>$row['due_on'],'state'=>$row['state'],'can_close'=>$active&&$row['state']==='open'&&(string)$a['teacher_id']===$actor->identityId&&in_array('teacher',$roles,true),
   'can_submit'=>$active&&$row['state']==='open'&&in_array('student',$roles,true)&&$e!==null&&(!$delivery||($delivery->current_assessment_id??null)===null&&(string)$delivery->accepted_under_enrollment_id===(string)$e['id'])];
 }
 public function activities(AuthenticatedActor $actor,string $assignment,?string $after):array {
  $a=$this->assignment($assignment);$roles=$this->roles($actor);$potential=(string)$a['teacher_id']===$actor->identityId&&in_array('teacher',$roles,true)||in_array('student',$roles,true)&&count($this->enrollments($actor,$a))>0;if(!$potential)throw new AcademicCommandFailure('not_found');
  $q=$this->db->table('activity_references as r')->join('activity_contents as c','c.activity_id','=','r.id')->where('r.teaching_assignment_id',$assignment);if($after!==null)$q->where('r.id','>',AcademicLockSet::id($after));$rows=$q->orderBy('r.id')->limit(50)->get(['r.teaching_assignment_id','c.*']);$items=[];foreach($rows as $r)if($this->canRead($actor,(array)$r))$items[]=$this->view($actor,(array)$r);return ['items'=>$items,'next_after'=>$rows->count()===50?(string)$rows->last()->activity_id:null];
 }
 public function deliveries(AuthenticatedActor $actor,string $activity,?string $after):array {
  $row=$this->activity($actor,$activity);$a=$this->assignment((string)$row['teaching_assignment_id']);$roles=$this->roles($actor);$teacher=(string)$a['teacher_id']===$actor->identityId&&in_array('teacher',$roles,true);
  $q=$this->db->table('activity_deliveries as d')->join('submission_references as r','r.id','=','d.submission_id')->join('retained_identity_profiles as p','p.identity_id','=','d.student_id')->where('d.activity_id',$activity);if(!$teacher)$q->where('d.student_id',$actor->identityId);if($after!==null)$q->where('d.submission_id','>',AcademicLockSet::id($after));$rows=$q->orderBy('d.submission_id')->limit(51)->get(['d.*','r.accepted_under_enrollment_id','r.accepted_at','p.display_name']);$more=$rows->count()>50;
  $items=[];foreach($rows->take(50) as $r){$v=$this->db->table('delivery_versions')->where('id',$r->current_version_id)->where('submission_id',$r->submission_id)->first();if(!$v)throw new AcademicCommandFailure('reference_unavailable');$items[]=['id'=>(string)$r->submission_id,'student_name'=>$r->display_name,'accepted_at'=>$r->accepted_at,'version'=>$this->version((array)$v)]+(new DeliveryAssessment($this->db))->projection($actor,(string)$r->submission_id);}return ['items'=>$items,'next_after'=>$more?end($items)['id']:null];
 }
 private function version(array $r):array {return ['id'=>(string)$r['id'],'answer'=>$r['answer'],'filename'=>$r['filename'],'bytes'=>$r['bytes']===null?null:(int)$r['bytes'],'recorded_at'=>$r['recorded_at']];}
 private function authorizedDelivery(AuthenticatedActor $actor,string $id):array {$r=$this->db->table('activity_deliveries as d')->join('submission_references as s','s.id','=','d.submission_id')->where('d.submission_id',AcademicLockSet::id($id))->first(['d.*','s.teaching_assignment_id']);if(!$r)throw new AcademicCommandFailure('not_found');$roles=$this->roles($actor);$a=$this->assignment((string)$r->teaching_assignment_id);if(!((string)$r->student_id===$actor->identityId&&in_array('student',$roles,true)||(string)$a['teacher_id']===$actor->identityId&&in_array('teacher',$roles,true)))throw new AcademicCommandFailure('not_found');return (array)$r;}
 public function versions(AuthenticatedActor $actor,string $id,?string $after):array {$this->authorizedDelivery($actor,$id);$q=$this->db->table('delivery_versions')->where('submission_id',$id);if($after!==null)$q->where('id','>',AcademicLockSet::id($after));$rows=$q->orderBy('id')->limit(51)->get();$more=$rows->count()>50;$items=$rows->take(50)->map(fn($r)=>$this->version((array)$r))->values()->all();return ['items'=>$items,'next_after'=>$more?end($items)['id']:null];}
 public function file(AuthenticatedActor $actor,string $version):array {$v=$this->db->table('delivery_versions')->where('id',AcademicLockSet::id($version))->first();if(!$v||$v->storage_key===null)throw new AcademicCommandFailure('not_found');$this->authorizedDelivery($actor,(string)$v->submission_id);return [$this->storage->verify((array)$v),(array)$v];}
 public function write(AuthenticatedActor $actor,string $operation,string $id,array $input,?string $path=null,?string $filename=null):array {
  $this->roles($actor);$id=AcademicLockSet::id($id);$meta=['filename'=>null,'storage_key'=>null,'mime'=>null,'bytes'=>null,'sha256'=>null];$key=null;$lock=null;$keep=false;
  if($operation==='publish'){FoundationCommandChecks::fields($input,['title','instructions','due_on'],['title','instructions']);foreach(['title'=>200,'instructions'=>10000] as $field=>$max)if(!is_string($input[$field])||!mb_check_encoding($input[$field],'UTF-8')||trim($input[$field])===''||mb_strlen($input[$field])>$max)throw new AcademicCommandFailure('invalid_input');$due=$input['due_on']??null;if($due!==null){if(!is_string($due))throw new AcademicCommandFailure('invalid_input');try{new \App\Domain\Academic\DeclaredDateRange($due);}catch(\InvalidArgumentException){throw new AcademicCommandFailure('invalid_input');}if($due<(new \DateTimeImmutable('now',new \DateTimeZone('America/Lima')))->format('Y-m-d'))throw new AcademicCommandFailure('invalid_input');}}
  elseif($operation==='submit'){FoundationCommandChecks::fields($input,['answer']);$answer=$input['answer']??'';if(!is_string($answer)||!mb_check_encoding($answer,'UTF-8')||mb_strlen($answer)>10000||trim($answer)===''&&$path===null)throw new AcademicCommandFailure('invalid_input');if($path!==null){$meta=(new DeliveryFileValidator)->validate($path,$filename??'')+['filename'=>$filename];[$key,$lock]=$this->storage->finalize($path);$meta['storage_key']=$key;$this->storage->verify($meta);}}
  elseif($operation==='close')FoundationCommandChecks::fields($input,[]);else throw new AcademicCommandFailure('invalid_input');
  $enrollment=null;$existing=null;
  try{$result=(new AcademicWriteTransaction($this->db))->execute($actor->identityId,
   function($db,$actorId,$context)use($operation,$id,$actor){$activity=$operation==='publish'?null:(array)$this->db->table('activity_references')->where('id',$id)->first();$assignment=$operation==='publish'?$id:($activity['teaching_assignment_id']??null);$a=$assignment===null?[]:(array)$this->db->table('teaching_assignments')->where('id',$assignment)->first();$e=$operation==='submit'?$this->db->table('student_enrollments')->where('student_id',$actor->identityId)->where('academic_period_id',$a['academic_period_id']??null)->pluck('id')->all():[];$s=$operation==='submit'?$this->db->table('activity_deliveries')->where('student_id',$actor->identityId)->where('activity_id',$id)->pluck('submission_id')->all():[];
    return new AcademicLockSet(['academic_periods'=>isset($a['academic_period_id'])?[$a['academic_period_id']]:[],'retained_identities'=>isset($a['teacher_id'])?[$a['teacher_id']]:[],'student_enrollments'=>$e,'teaching_assignments'=>$assignment===null?[]:[$assignment],'activity_references'=>$operation==='publish'?[]:[$id],'submission_references'=>$s]);},
   function($context,$ordinal)use($actor,$operation,$id,&$enrollment,&$existing){$roles=$this->roles($actor);$activity=$operation==='publish'?null:$this->content($id);$a=$context->row('teaching_assignments',$operation==='publish'?$id:$activity['teaching_assignment_id']);if($context->row('academic_periods',$a['academic_period_id'])['state']!=='active')throw new AcademicCommandFailure('period_not_active');
    if($operation!=='submit'){if((string)$a['teacher_id']!==$actor->identityId||!in_array('teacher',$roles,true))throw new AcademicCommandFailure('forbidden');if($operation==='publish'&&$a['state']!=='active'||$operation==='close'&&$activity['state']!=='open')throw new AcademicCommandFailure('invalid_transition');}
    else{if(!in_array('student',$roles,true))throw new AcademicCommandFailure('forbidden');if($activity['state']!=='open')throw new AcademicCommandFailure('activity_closed');$active=array_values(array_filter($context->rows('student_enrollments'),fn($e)=>$e['state']==='active'&&$e['operational_start_key']!==null&&(int)$e['operational_start_key']<=$ordinal&&($e['operational_end_key']===null||(int)$e['operational_end_key']>$ordinal)));if(count($active)!==1)throw new AcademicCommandFailure('no_active_enrollment');$enrollment=$active[0];foreach(['academic_period_id','grade_id','section_id'] as $field)if((string)$a[$field]!==(string)$enrollment[$field])throw new AcademicCommandFailure('scope_mismatch');$existing=$this->db->table('activity_deliveries')->where('student_id',$actor->identityId)->where('activity_id',$id)->first();if($existing&&($existing->current_assessment_id??null)!==null)throw new AcademicCommandFailure('already_assessed');if($existing&&(string)$context->row('submission_references',$existing->submission_id)['accepted_under_enrollment_id']!==(string)$enrollment['id'])throw new AcademicCommandFailure('historical_read_only');}return true;},
   function($context,$boundary)use($actor,$operation,$id,$input,$meta,&$enrollment,&$existing){$stamp=$boundary->timestamp->format('Y-m-d H:i:s.u');$assignment=$operation==='publish'?$id:(string)$this->content($id)['teaching_assignment_id'];
    if($operation==='publish'){$activity=(string)$this->db->table('activity_references')->insertGetId(['teaching_assignment_id'=>$id]);$this->db->table('activity_contents')->insert(['activity_id'=>$activity,'title'=>$input['title'],'instructions'=>$input['instructions'],'due_on'=>$input['due_on']??null,'state'=>'open','publication_key'=>$boundary->toServerKey(),'published_at'=>$stamp]);$value=['id'=>$activity];$event='activity_published';}
    elseif($operation==='close'){$this->db->table('activity_contents')->where('activity_id',$id)->update(['state'=>'closed']);$value=['id'=>$id];$event='activity_closed';}
    else{if($existing)$submission=(string)$existing->submission_id;else{$submission=(string)$this->db->table('submission_references')->insertGetId(['student_id'=>$actor->identityId,'activity_id'=>$id,'teaching_assignment_id'=>$assignment,'accepted_under_enrollment_id'=>$enrollment['id'],'accepted_at'=>$stamp,'acceptance_operation_key'=>$boundary->toServerKey()]);$this->db->table('activity_deliveries')->insert(['submission_id'=>$submission,'student_id'=>$actor->identityId,'activity_id'=>$id]);}$version=(string)$this->db->table('delivery_versions')->insertGetId($meta+['submission_id'=>$submission,'answer'=>$input['answer']??'','operation_key'=>$boundary->toServerKey(),'recorded_at'=>$stamp]);$this->db->table('activity_deliveries')->where('submission_id',$submission)->update(['current_version_id'=>$version]);$value=['id'=>$submission,'version_id'=>$version];$event=$existing?'delivery_updated':'delivery_accepted';}
    $notices=new AcademicNotifications($this->db);$a=$context->row('teaching_assignments',$assignment);if($operation==='publish')$notices->emit($event,$notices->publicationRecipients($a,$boundary->toServerKey()),$value['id'],null,$boundary->toServerKey(),$stamp);elseif($operation==='submit')$notices->emit($event,[(string)$a['teacher_id']],null,$value['id'],$boundary->toServerKey(),$stamp);
    return new AcademicMutationResult($value,[new LifecycleEvent('assignment',$assignment,$event,null,null,['resource_id'=>$value['id']])]);});$keep=true;return $result;
  }catch(AcademicTransactionFailure $e){$keep=in_array($e->category,['commit_outcome_unknown','rollback_outcome_unknown'],true);throw $e;}finally{if($key!==null){try{if(!$keep)$this->storage->remove($key);}finally{$this->storage->release($key,$lock);}}}
 }
}
